package sorting

import (
	"reflect"
	"testing"
)

func TestCountingSortBasic(t *testing.T) {
	got := CountingSort([]int{4, 2, 2, 8, 3, 3, 1})
	want := []int{1, 2, 2, 3, 3, 4, 8}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("want %v got %v", want, got)
	}
}

func TestCountingSortEmpty(t *testing.T) {
	got := CountingSort([]int{})
	if len(got) != 0 {
		t.Fatalf("expected empty, got %v", got)
	}
}

func TestRadixSortBasic(t *testing.T) {
	got := RadixSort([]int{170, 45, 75, 90, 802, 24, 2, 66})
	want := []int{2, 24, 45, 66, 75, 90, 170, 802}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("want %v got %v", want, got)
	}
}

func TestRadixSortSingleDigits(t *testing.T) {
	got := RadixSort([]int{5, 3, 8, 1, 9, 2})
	want := []int{1, 2, 3, 5, 8, 9}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("want %v got %v", want, got)
	}
}

func TestRadixSortEmpty(t *testing.T) {
	got := RadixSort([]int{})
	if len(got) != 0 {
		t.Fatalf("expected empty, got %v", got)
	}
}

